    public TFMRequestFiltersElement parmFilters(TFMRequestFiltersElement _filters = filters)
    {
        filters = _filters;
		if (!filters)
        {
            filters = new TFMRequestFiltersElement();
            filters.parmInitFromParmFilter(true);
		}
        return filters;
    }
